<?php require 'config.php'; require_admin(); $msg=''; $students=$conn->query('SELECT * FROM students ORDER BY name'); $subjects=$conn->query('SELECT * FROM subjects ORDER BY subject_name'); if(isset($_POST['save'])){$sid=(int)$_POST['student_id'];foreach($_POST['mark'] as $subid=>$mark){if($mark==='')continue;$subid=(int)$subid;$mark=(float)$mark;$stmt=$conn->prepare('INSERT INTO marks(student_id,subject_id,marks_obtained) VALUES(?,?,?) ON DUPLICATE KEY UPDATE marks_obtained=VALUES(marks_obtained)');$stmt->bind_param('iid',$sid,$subid,$mark);$stmt->execute();}$msg='Marks saved successfully.';} $page_title='Enter Marks'; require 'header.php'; ?>
<div class="page-head"><h1>Enter Marks</h1><p>Select a student and save marks subject by subject.</p></div><form class="panel marks-form" method="post"><?php if($msg):?><p class="alert"><?=e($msg)?></p><?php endif;?><label>Student</label><select name="student_id" required><option value="">Choose student</option><?php while($st=$students->fetch_assoc()):?><option value="<?=$st['id']?>"><?=e($st['roll_no'].' — '.$st['name'])?></option><?php endwhile;?></select><div class="mark-grid"><?php while($su=$subjects->fetch_assoc()):?><div><label><?=e($su['subject_name'])?> <small>(max <?=$su['max_marks']?>)</small></label><input type="number" step="0.01" min="0" max="<?=$su['max_marks']?>" name="mark[<?=$su['id']?>]" placeholder="Marks"></div><?php endwhile;?></div><button name="save">Save Marks</button></form>
<?php require 'footer.php'; ?>
